mapper.select:
SELECT
  (SELECT IFNULL(SUM(amount),0) FROM recharge_order
     WHERE store_id = #{storeId}
     AND created_at >= #{from}
     AND created_at < #{to}) AS revenue,
  (SELECT IFNULL(SUM(hours+gift_hours),0) FROM recharge_order
     WHERE store_id = #{storeId}
     AND created_at >= #{from}
     AND created_at < #{to}) AS rechargeHours,
  (SELECT COUNT(*) FROM checkin
     WHERE store_id = #{storeId}
     AND check_time >= #{from}
     AND check_time < #{to}) AS checkinCount,
  (SELECT COUNT(DISTINCT user_id) FROM checkin
     WHERE store_id = #{storeId}
     AND check_time >= #{from}
     AND check_time < #{to}) AS activeUsers,
  (SELECT COUNT(*) FROM `user` WHERE store_id = #{storeId} AND status = 1) AS userTotal
